/* @autogenerated */
package net.civeira.phylax.common.security.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.time.ZonedDateTime;
import java.util.Locale;
import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.security.InvocationChannel;
import net.civeira.phylax.common.security.InvocationSource;

@DisplayName("InvocationSourceImpl map conversion")
class InvocationSourceImplUnitTest {

  @Test
  @DisplayName("Should round-trip every field through a map")
  void shouldRoundTripThroughMap() {
    // Arrange — a fully populated source
    ZonedDateTime start = ZonedDateTime.parse("2026-01-02T03:04:05Z");
    InvocationSource source =
        InvocationSourceImpl.builder().channel(InvocationChannel.WEB).requestId("req")
            .clientId("client").application("app").device("dev").host("host").ip("1.2.3.4")
            .userAgent("agent").locale(Locale.forLanguageTag("es-ES")).startTime(start).build();

    // Act — convert to a map and back
    InvocationSource restored = InvocationSourceImpl.fromMap(InvocationSourceImpl.toMap(source));

    // Assert — all values survive the conversion
    assertEquals(InvocationChannel.WEB, restored.getChannel());
    assertEquals("req", restored.getRequestId());
    assertEquals("client", restored.getClientId());
    assertEquals("app", restored.getApplication());
    assertEquals("dev", restored.getDevice());
    assertEquals("host", restored.getHost());
    assertEquals("1.2.3.4", restored.getIp());
    assertEquals("agent", restored.getUserAgent());
    assertEquals(Locale.forLanguageTag("es-ES"), restored.getLocale());
    assertEquals(start, restored.getStartTime());
  }

  @Test
  @DisplayName("Should use empty strings for missing optional values")
  void shouldUseEmptyStringsForMissingValues() {
    // Act — build from a map with only the mandatory values
    InvocationSource restored = InvocationSourceImpl
        .fromMap(Map.of("channel", "BATCH", "startTime", "2026-01-02T03:04:05Z"));

    // Assert — optional values become empty
    assertEquals(InvocationChannel.BATCH, restored.getChannel());
    assertEquals("", restored.getRequestId());
    assertEquals("", restored.getIp());
  }
}
